// dist/cli/ui/spinner.js
var Spinner = class {
  text;
  color;
  frames;
  interval;
  currentFrame = 0;
  timer = null;
  stream = process.stderr;
  constructor(options = {}) {
    const theme = getTheme();
    this.text = options.text ?? "Loading...";
    this.color = options.color ?? theme.colors.primary;
    this.frames = options.frames ?? theme.symbols.spinner;
    this.interval = options.interval ?? 80;
  }
  start(text) {
    if (text)
      this.text = text;
    if (this.timer)
      return this;
    this.stream.write("\x1B[?25l");
    this.timer = setInterval(() => {
      this.render();
      this.currentFrame = (this.currentFrame + 1) % this.frames.length;
    }, this.interval);
    return this;
  }
  render() {
    const frame = this.color(this.frames[this.currentFrame]);
    this.stream.write(`\r${frame} ${this.text}`);
  }
  update(text) {
    this.text = text;
    return this;
  }
  stop() {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    this.stream.write("\r\x1B[K\x1B[?25h");
    return this;
  }
  success(text) {
    this.stopWithSymbol("success", text);
  }
  error(text) {
    this.stopWithSymbol("error", text);
  }
  warn(text) {
    this.stopWithSymbol("warning", text);
  }
  info(text) {
    this.stopWithSymbol("info", text);
  }
  stopWithSymbol(type, text) {
    if (this.timer) {
      clearInterval(this.timer);
      this.timer = null;
    }
    const theme = getTheme();
    const symbol = theme.symbols[type];
    const color = theme.colors[type];
    const message = text ?? this.text;
    this.stream.write(`\r\x1B[K${color(symbol)} ${message}
\x1B[?25h`);
  }
};
function spinner(options) {
  if (typeof options === "string") {
    return new Spinner({ text: options });
  }
  return new Spinner(options);
}

// dist/cli/ui/progress.js
var Progress = class {
  current = 0;
  total;
  width;
  complete;
  incomplete;
  head;
  showPercent;
  showEta;
  showValue;
  startTime = Date.now();
  stream = process.stderr;
  label = "";
  constructor(options = {}) {
    this.total = options.total ?? 100;
    this.width = options.width ?? 30;
    this.complete = options.complete ?? "\u2588";
    this.incomplete = options.incomplete ?? "\u2591";
    this.head = options.head ?? "\u2588";
    this.showPercent = options.showPercent ?? true;
    this.showEta = options.showEta ?? true;
    this.showValue = options.showValue ?? false;
  }
  start(label) {
    if (label)
      this.label = label;
    this.startTime = Date.now();
    this.current = 0;
    this.stream.write("\x1B[?25l");
    this.render();
    return this;
  }
  update(value, label) {
    this.current = Math.min(value, this.total);
    if (label)
      this.label = label;
    this.render();
    return this;
  }
  increment(amount = 1) {
    return this.update(this.current + amount);
  }
  render() {
    const theme = getTheme();
    const percent = this.current / this.total;
    const completed = Math.floor(this.width * percent);
    const remaining = this.width - completed;
    let bar = "";
    if (completed > 0) {
      bar += theme.colors.primary(this.complete.repeat(completed - 1));
      bar += theme.colors.highlight(this.head);
    }
    bar += theme.colors.muted(this.incomplete.repeat(remaining));
    const parts = [];
    if (this.label) {
      parts.push(this.label);
    }
    parts.push(bar);
    if (this.showPercent) {
      parts.push(theme.colors.text(`${Math.floor(percent * 100)}%`));
    }
    if (this.showValue) {
      parts.push(theme.colors.muted(`(${this.current}/${this.total})`));
    }
    if (this.showEta && percent > 0 && percent < 1) {
      const elapsed = (Date.now() - this.startTime) / 1e3;
      const estimatedTotal = elapsed / percent;
      const eta = Math.ceil(estimatedTotal - elapsed);
      parts.push(theme.colors.muted(`(${formatTime(eta)})`));
    }
    this.stream.write(`\r\x1B[K${parts.join(" ")}`);
  }
  done(message) {
    const theme = getTheme();
    this.current = this.total;
    this.stream.write("\r\x1B[K");
    if (message) {
      this.stream.write(`${theme.colors.success(theme.symbols.success)} ${message}
`);
    } else {
      const elapsed = (Date.now() - this.startTime) / 1e3;
      this.stream.write(`${theme.colors.success(theme.symbols.success)} ${this.label || "Complete"} ${theme.colors.muted(`(${formatTime(elapsed)})`)}
`);
    }
    this.stream.write("\x1B[?25h");
  }
  fail(message) {
    const theme = getTheme();
    this.stream.write("\r\x1B[K");
    this.stream.write(`${theme.colors.error(theme.symbols.error)} ${message || "Failed"}
`);
    this.stream.write("\x1B[?25h");
  }
};
function formatTime(seconds) {
  if (seconds < 60) {
    return `${Math.ceil(seconds)}s`;
  } else if (seconds < 3600) {
    const mins = Math.floor(seconds / 60);
    const secs = Math.ceil(seconds % 60);
    return `${mins}m ${secs}s`;
  } else {
    const hours = Math.floor(seconds / 3600);
    const mins = Math.floor(seconds % 3600 / 60);
    return `${hours}h ${mins}m`;
  }
}
function progress(options) {
  return new Progress(options);
}

// dist/cli/ui/box.js
function getTerminalWidth() {
  return process.stdout.columns ?? 80;
}
function stripAnsi(str) {
  return str.replace(/\x1b\[[0-9;]*m/g, "");
}
function pad(str, width, align = "left") {
  const visibleLength = stripAnsi(str).length;
  const padding = width - visibleLength;
  if (padding <= 0)
    return str;
  switch (align) {
    case "center": {
      const left = Math.floor(padding / 2);
      const right = padding - left;
      return " ".repeat(left) + str + " ".repeat(right);
    }
    case "right":
      return " ".repeat(padding) + str;
    default:
      return str + " ".repeat(padding);
  }
}
function box(content, options = {}) {
  const theme = getTheme();
  const { title, padding = 1, margin = 0, borderColor = theme.colors.primary, titleColor = theme.colors.highlight, width = "auto", align = "left" } = options;
  const { topLeft, topRight, bottomLeft, bottomRight, horizontal, vertical } = theme.box;
  const lines = Array.isArray(content) ? content : content.split("\n");
  const termWidth = getTerminalWidth();
  const maxLineWidth = Math.max(...lines.map((l) => stripAnsi(l).length));
  const titleWidth = title ? stripAnsi(title).length + 2 : 0;
  let innerWidth;
  if (width === "auto") {
    innerWidth = Math.max(maxLineWidth, titleWidth) + padding * 2;
  } else {
    innerWidth = Math.min(width, termWidth - 4) - 2;
  }
  const marginStr = " ".repeat(margin);
  const paddingStr = " ".repeat(padding);
  const result = [];
  if (title) {
    const titleStr = ` ${titleColor(title)} `;
    const leftBorder = horizontal.repeat(2);
    const rightBorderLen = innerWidth - 4 - stripAnsi(title).length;
    const rightBorder = horizontal.repeat(Math.max(0, rightBorderLen));
    result.push(marginStr + borderColor(topLeft + leftBorder) + titleStr + borderColor(rightBorder + topRight));
  } else {
    result.push(marginStr + borderColor(topLeft + horizontal.repeat(innerWidth) + topRight));
  }
  for (const line of lines) {
    const paddedLine = pad(line, innerWidth - padding * 2, align);
    result.push(marginStr + borderColor(vertical) + paddingStr + paddedLine + paddingStr + borderColor(vertical));
  }
  result.push(marginStr + borderColor(bottomLeft + horizontal.repeat(innerWidth) + bottomRight));
  return result.join("\n");
}
function header(title, subtitle) {
  const theme = getTheme();
  const content = subtitle ? [title, theme.colors.muted(subtitle)] : [title];
  return box(content, {
    borderColor: theme.colors.primary,
    titleColor: theme.colors.highlight,
    align: "center",
    padding: 2
  });
}

