  print(`  ${theme.colors.highlight("--wait, -w")}     ${theme.colors.muted("Wait for completion (can take several minutes)")}`);
  print(`  ${theme.colors.highlight("--negative")}     ${theme.colors.muted('Things to avoid (e.g., "text, watermarks")')}`);
