import * as fs10 from "fs";
import * as path9 from "path";
function saveWavFile(filename, pcmData, channels = 1, sampleRate = 24e3, bitsPerSample = 16) {
  const outputDir2 = ensureOutputDir();
  const filePath = path9.join(outputDir2, filename);
  const byteRate = sampleRate * channels * bitsPerSample / 8;
  const blockAlign = channels * bitsPerSample / 8;
  const dataSize = pcmData.length;
  const headerSize = 44;
  const fileSize = headerSize + dataSize - 8;
  const header2 = Buffer.alloc(headerSize);
  header2.write("RIFF", 0);
  header2.writeUInt32LE(fileSize, 4);
  header2.write("WAVE", 8);
  header2.write("fmt ", 12);
  header2.writeUInt32LE(16, 16);
  header2.writeUInt16LE(1, 20);
  header2.writeUInt16LE(channels, 22);
  header2.writeUInt32LE(sampleRate, 24);
  header2.writeUInt32LE(byteRate, 28);
  header2.writeUInt16LE(blockAlign, 32);
  header2.writeUInt16LE(bitsPerSample, 34);
  header2.write("data", 36);
  header2.writeUInt32LE(dataSize, 40);
  fs10.writeFileSync(filePath, Buffer.concat([header2, pcmData]));
  return filePath;
}
